CREATE OR REPLACE FUNCTION public.validate_invoice_job_charge() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE j public.jobs%ROWTYPE; inv public.invoices%ROWTYPE; BEGIN SELECT * INTO inv FROM public.invoices WHERE id=NEW.invoice_id; IF inv.id IS NULL OR inv.company_id<>NEW.company_id THEN RAISE EXCEPTION 'Invoice company must match'; END IF; IF NEW.job_id IS NOT NULL THEN SELECT * INTO j FROM public.jobs WHERE id=NEW.job_id FOR UPDATE; IF j.id IS NULL OR j.company_id<>NEW.company_id OR j.customer_id<>inv.customer_id THEN RAISE EXCEPTION 'Visit must belong to the invoice customer and company'; END IF; IF j.monthly_included THEN RAISE EXCEPTION 'This visit is included in the monthly service amount'; END IF; IF EXISTS(SELECT 1 FROM public.invoice_items i WHERE i.job_id=NEW.job_id AND i.id<>NEW.id) THEN RAISE EXCEPTION 'This visit has already been billed'; END IF; END IF; RETURN NEW; END $$;
CREATE TRIGGER validate_invoice_job_charge BEFORE INSERT OR UPDATE ON public.invoice_items FOR EACH ROW EXECUTE FUNCTION public.validate_invoice_job_charge();